import{_ as e,a as o,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Remove Cart Item","description":"","frontmatter":{"outline":false,"examples":[{"id":"remove-cart-item-simple","title":"Remove Item from Cart","description":"Remove a specific item from the shopping cart.","query":"mutation removeItem(\\n    $cartItemId: Int!\\n) {\\n  createRemoveCartItem(\\n    input: { cartItemId: $cartItemId}\\n  ) {\\n    removeCartItem {\\n      id\\n      _id\\n      cartToken\\n      items {\\n        totalCount\\n        edges {\\n          node {\\n            id\\n            cartId\\n            productId\\n            name\\n            sku\\n            quantity\\n            price\\n            basePrice\\n            total\\n            baseTotal\\n            productUrlKey\\n            canChangeQty\\n          }\\n        }\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n    \\"cartItemId\\": 54\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createRemoveCartItem\\": {\\n      \\"removeCartItem\\": {\\n        \\"id\\": \\"/api/shop/carts/1\\",\\n        \\"_id\\": 1,\\n        \\"cartToken\\": \\"d5f1c0b1e4a94f4f8f0d2c7b6a3e9f21\\",\\n        \\"itemsCount\\": 1,\\n        \\"success\\": true,\\n        \\"message\\": \\"Item removed from cart successfully\\",\\n        \\"items\\": {\\n          \\"totalCount\\": 1,\\n          \\"edges\\": [\\n            {\\n              \\"node\\": {\\n                \\"id\\": \\"/api/shop/cart-items/55\\",\\n                \\"_id\\": 55,\\n                \\"cartId\\": 1,\\n                \\"productId\\": 24,\\n                \\"name\\": \\"EverFresh Men's Wrinkle-Free Half Sleeve 100% Cotton Tee\\",\\n                \\"sku\\": \\"ms-everfresh-tee\\",\\n                \\"quantity\\": 1,\\n                \\"price\\": 42.99,\\n                \\"total\\": 42.99,\\n                \\"productUrlKey\\": \\"everfresh-mens-wrinkle-free-half-sleeve-100-cotton-tee\\",\\n                \\"canChangeQty\\": true\\n              }\\n            }\\n          ]\\n        }\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"Authentication token is required","cause":"Neither a customer Bearer token nor a guest cart token was sent","solution":"Send the customer's Bearer token, or the guest cart token from Create Cart"},{"error":"ITEM_NOT_FOUND","cause":"The cart item id does not belong to the current cart","solution":"Read the cart and use an id from items.edges[].node._id"},{"error":"CART_NOT_FOUND","cause":"No cart exists for the supplied token","solution":"Create a cart and add an item before removing one"}]},{"id":"remove-cart-items-bulk","title":"Remove Several Items at Once","description":"Remove more than one item in a single call with createRemoveCartItems, passing the cart item ids as itemIds. The payload is the updated cart, exactly as the single-item mutation returns.","query":"mutation removeItems(\\n    $itemIds: Iterable\\n) {\\n  createRemoveCartItems(\\n    input: { itemIds: $itemIds }\\n  ) {\\n    removeCartItems {\\n      id\\n      _id\\n      cartToken\\n      itemsCount\\n      success\\n      message\\n      grandTotal\\n      formattedGrandTotal\\n      items {\\n        totalCount\\n        edges {\\n          node {\\n            id\\n            _id\\n            name\\n            sku\\n            quantity\\n            total\\n          }\\n        }\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n    \\"itemIds\\": [54, 55]\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createRemoveCartItems\\": {\\n      \\"removeCartItems\\": {\\n        \\"id\\": \\"/api/shop/carts/1\\",\\n        \\"_id\\": 1,\\n        \\"cartToken\\": \\"d5f1c0b1e4a94f4f8f0d2c7b6a3e9f21\\",\\n        \\"itemsCount\\": 0,\\n        \\"success\\": true,\\n        \\"message\\": \\"Items removed from cart successfully\\",\\n        \\"grandTotal\\": 0,\\n        \\"formattedGrandTotal\\": \\"$0.00\\",\\n        \\"items\\": {\\n          \\"totalCount\\": 0,\\n          \\"edges\\": []\\n        }\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"Authentication token is required","cause":"Neither a customer Bearer token nor a guest cart token was sent","solution":"Send the customer's Bearer token, or the guest cart token from Create Cart"},{"error":"ITEM_NOT_FOUND","cause":"One of the supplied ids does not belong to the current cart","solution":"Read the cart first and send only ids from items.edges[].node._id"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/mutations/remove-cart-item.md","filePath":"api/graphql-api/shop/mutations/remove-cart-item.md","lastUpdated":1786429091000}`),d={name:"api/graphql-api/shop/mutations/remove-cart-item.md"};function n(i,t,c,s,l,h){return a(),o("div",null,t[0]||(t[0]=[r('<h1 id="remove-cart-item" tabindex="-1">Remove Cart Item <a class="header-anchor" href="#remove-cart-item" aria-label="Permalink to &quot;Remove Cart Item&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>Two mutations remove items from the cart:</p><ul><li><strong><code>createRemoveCartItem</code></strong> takes one <code>cartItemId</code> and drops that line.</li><li><strong><code>createRemoveCartItems</code></strong> takes an <code>itemIds</code> list and drops several in a single call.</li></ul><p>Both recalculate the cart&#39;s totals, discounts, and taxes, and both return the <strong>updated cart</strong> rather than the item that went — so a client can re-render the cart straight from the response with no follow-up read. Use the bulk form for a &quot;remove selected&quot; control; calling the single form in a loop re-runs the totals for every item.</p><p>Removing the last item leaves the cart empty but still readable. The cart itself only disappears once the session ends.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Both mutations work for a signed-in customer and for a guest:</p><ul><li><strong>Authenticated customers</strong> — send the customer token in the <code>Authorization</code> header, obtained from <a href="/api/graphql-api/shop/mutations/customer-login.html">Customer Login</a>.</li><li><strong>Guests</strong> — send the cart token from <a href="/api/graphql-api/shop/mutations/create-cart.html">Create Cart</a>.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer &lt;accessToken&gt;</span></span></code></pre></div><p>Sending neither fails with <em>&quot;Authentication token is required&quot;</em> before the cart is touched.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><h3 id="single-item-—-createremovecartitem" tabindex="-1">Single item — <code>createRemoveCartItem</code> <a class="header-anchor" href="#single-item-—-createremovecartitem" aria-label="Permalink to &quot;Single item — `createRemoveCartItem`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>cartItemId</code></td><td><code>Int</code></td><td>✅ Yes</td><td>Numeric id of the cart item to remove. Take it from <code>items.edges[].node._id</code> on any cart response.</td></tr><tr><td><code>clientMutationId</code></td><td><code>String</code></td><td>❌ No</td><td>Arbitrary string echoed back in the payload.</td></tr></tbody></table><h3 id="several-items-—-createremovecartitems" tabindex="-1">Several items — <code>createRemoveCartItems</code> <a class="header-anchor" href="#several-items-—-createremovecartitems" aria-label="Permalink to &quot;Several items — `createRemoveCartItems`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>itemIds</code></td><td><code>Iterable</code></td><td>✅ Yes</td><td>List of numeric cart item ids, e.g. <code>[54, 55]</code>.</td></tr><tr><td><code>clientMutationId</code></td><td><code>String</code></td><td>❌ No</td><td>Arbitrary string echoed back in the payload.</td></tr></tbody></table><p>The input type these mutations share is the cart-wide input used across every cart operation, so the schema also lists fields such as <code>productId</code> and <code>couponCode</code>. Only the ones above apply here; anything else is ignored.</p><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><p>The payload wraps the updated cart — <code>removeCartItem</code> on the single mutation, <code>removeCartItems</code> on the bulk one. Both carry the same fields.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>IRI-style cart identifier.</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Numeric cart id.</td></tr><tr><td><code>cartToken</code></td><td><code>String</code></td><td>Token identifying this cart, for guest sessions.</td></tr><tr><td><code>itemsCount</code></td><td><code>Int</code></td><td>Number of line items left in the cart.</td></tr><tr><td><code>itemsQty</code></td><td><code>Int</code></td><td>Total units across those lines.</td></tr><tr><td><code>success</code></td><td><code>Boolean</code></td><td>Whether the removal succeeded.</td></tr><tr><td><code>message</code></td><td><code>String</code></td><td>Result message.</td></tr><tr><td><code>items</code></td><td><code>CartItemCursorConnection</code></td><td>The remaining items — see below.</td></tr><tr><td><code>subtotal</code> / <code>formattedSubtotal</code></td><td><code>Float</code> / <code>String</code></td><td>Recalculated subtotal, raw and currency-formatted.</td></tr><tr><td><code>discountAmount</code> / <code>formattedDiscountAmount</code></td><td><code>Float</code> / <code>String</code></td><td>Recalculated discount.</td></tr><tr><td><code>taxAmount</code> / <code>formattedTaxAmount</code></td><td><code>Float</code> / <code>String</code></td><td>Recalculated tax.</td></tr><tr><td><code>shippingAmount</code> / <code>formattedShippingAmount</code></td><td><code>Float</code> / <code>String</code></td><td>Recalculated shipping.</td></tr><tr><td><code>grandTotal</code> / <code>formattedGrandTotal</code></td><td><code>Float</code> / <code>String</code></td><td>Recalculated grand total.</td></tr><tr><td><code>couponCode</code></td><td><code>String</code></td><td>Coupon still applied, or <code>null</code>.</td></tr><tr><td><code>isGuest</code></td><td><code>Boolean!</code></td><td>Whether the cart belongs to a guest.</td></tr></tbody></table><h3 id="remaining-item-fields" tabindex="-1">Remaining item fields <a class="header-anchor" href="#remaining-item-fields" aria-label="Permalink to &quot;Remaining item fields&quot;">​</a></h3><p>Each node in the <code>items</code> connection:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code> / <code>_id</code></td><td><code>ID!</code> / <code>Int</code></td><td>Cart item identifiers. <strong><code>_id</code> is what the remove mutations expect.</strong></td></tr><tr><td><code>productId</code></td><td><code>Int</code></td><td>Id of the product on this line.</td></tr><tr><td><code>name</code> / <code>sku</code></td><td><code>String</code></td><td>Product name and SKU.</td></tr><tr><td><code>quantity</code></td><td><code>Int</code></td><td>Units on this line.</td></tr><tr><td><code>price</code> / <code>total</code></td><td><code>Float</code></td><td>Unit price and line total.</td></tr><tr><td><code>formattedPrice</code> / <code>formattedTotal</code></td><td><code>String</code></td><td>The same values, currency-formatted.</td></tr><tr><td><code>productUrlKey</code></td><td><code>String</code></td><td>Storefront slug for linking back to the product.</td></tr><tr><td><code>canChangeQty</code></td><td><code>Boolean</code></td><td><code>false</code> for event and appointment bookings, whose quantity is fixed.</td></tr></tbody></table><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Send <code>_id</code>, not <code>id</code></strong> — the mutations take the numeric cart item id; the IRI form is rejected</li><li><strong>Use the bulk mutation for multi-select</strong> — one call recalculates totals once, where a loop over the single mutation recalculates them per item and returns a cart that is already stale by the next iteration</li><li><strong>Re-render from the payload</strong> — the response is the updated cart, so a follow-up <a href="/api/graphql-api/shop/queries/get-cart.html">Get Cart</a> is wasted work</li><li><strong>Expect an empty cart, not an error</strong> — removing the final item returns a cart with <code>itemsCount: 0</code>, which is a valid state to render</li><li><strong>Re-check the coupon</strong> — <code>couponCode</code> survives the removal, but the discount is recalculated against the smaller cart, so read the totals back rather than reusing the previous ones</li></ol><h2 id="error-scenarios" tabindex="-1">Error Scenarios <a class="header-anchor" href="#error-scenarios" aria-label="Permalink to &quot;Error Scenarios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Cause</th></tr></thead><tbody><tr><td>Authentication token is required</td><td>Neither a customer Bearer token nor a guest cart token was sent.</td></tr><tr><td>Item not found</td><td>The id does not belong to the current cart, or was already removed.</td></tr><tr><td>Cart not found</td><td>No cart exists for the supplied token.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/queries/get-cart.html">Get Cart</a> - Read the cart and its item ids</li><li><a href="/api/graphql-api/shop/mutations/add-to-cart.html">Add to Cart</a> - Add a product to the cart</li><li><a href="/api/graphql-api/shop/mutations/update-cart-item.html">Update Cart Item</a> - Change an item&#39;s quantity</li><li><a href="/api/graphql-api/shop/mutations/create-cart.html">Create Cart</a> - Start a guest cart</li><li><a href="/api/graphql-api/shop-api.html">Shop API Overview</a> - Overview of Shop API resources</li></ul>',29)]))}const p=e(d,[["render",n]]);export{u as __pageData,p as default};
